//! Cargo-driven `winhlp32.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is winhlp32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The C left, and its part of cmake's C rule; reactos-link adds what every C
    // compile shares from reactos-link/cflags/c.<arch>.flags (Linker::c_compiled).
    let c_sources: &[&str] = &["@build/base/applications/winhlp32/macro.lex.yy.c"];
    let c_includes: &[&str] = &[
        "@build/base/applications/winhlp32",
        "base/applications/winhlp32",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let c_flags: &[&str] = match arch.as_str() {
        "x86" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "@core",
        ],
        "x86_64" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "-U_X86_",
            "-UWIN32",
            "@core",
        ],
        "aarch64" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "@core",
        ],
        _ => unreachable!(),
    };
    let c_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
        "__WINESRC__",
        "strcasecmp=_stricmp",
    ];

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/applications/winhlp32",
        "base/applications/winhlp32",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x502", "__WINESRC__", "strcasecmp=_stricmp"];

    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_WinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "WinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "WinMainCRTStartup"),
        o => panic!("winhlp32-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:oldnames"],
        "x86_64" => &["engine:wine", "engine:oldnames"],
        "aarch64" => &["engine:wine", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("winhlp32-rust")
        .c_compiled("winhlp32_shims", c_sources, c_includes, c_flags, c_defines)
        .rc("base/applications/winhlp32/rsrc.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/comdlg32/comdlg32.spec", "comdlg32.dll", "comdlg32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::ExeAnsi)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
